const esc = (value) => String(value ?? "").replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;", "'":"&#39;"}[ch]));
const slug = (value) => value.toLowerCase().replace(/[^a-z0-9_]+/g, "-");

function renderTeam() {
  const host = document.getElementById("teamGrid");
  host.innerHTML = TEAM.map(person => `
    <article class="team-member">
      <div class="team-avatar">${person.name.split(" ").map(x=>x[0]).slice(0,2).join("")}</div>
      <div><strong>${esc(person.name)}</strong><small>${esc(person.student_id)} · ${esc(person.role)}</small></div>
    </article>`).join("");
}

function privacyBadge(code, note) {
  const cls = code === "DPS" ? "dps" : (code === "DP" ? "dp" : "na");
  return `<span class="privacy-badge ${cls}" title="${esc(note)}">[${esc(code)}]</span>`;
}

function constraintBadges(items) {
  return items.map(item => `<span class="constraint-badge">${esc("["+item+"]")}</span>`).join(" ");
}

function renderFieldRow(table, field) {
  const searchable = [table.name, field.name, field.description, field.type, field.constraints.join(" "), field.lineage, field.privacy, field.rbac_text].join(" ").toLowerCase();
  return `<tr class="field-row" data-privacy="${esc(field.privacy)}" data-search="${esc(searchable)}">
    <td class="attribute-cell"><code>${esc(field.name)}</code></td>
    <td class="description-cell">${esc(field.description)}${field.comment ? `<div class="column-comment">Comentário DDL: ${esc(field.comment)}</div>` : ""}</td>
    <td><span class="sql-type">${esc(field.type)}</span></td>
    <td class="constraints-cell">${constraintBadges(field.constraints)}${field.generated_expr ? `<div class="generated-expression">Expressão: <code>${esc(field.generated_expr)}</code></div>` : ""}</td>
    <td>${privacyBadge(field.privacy, field.privacy_note)}</td>
    <td class="lineage-cell">${esc(field.lineage)}</td>
    <td class="rbac-cell">${esc(field.rbac_text)}</td>
  </tr>`;
}

function renderTable(table) {
  const id = `tabela_${table.name}`;
  const fkHtml = table.fks.length ? table.fks.map(fk => `<li><code>${esc(fk.columns.join(", "))}</code> → <code>${esc(fk.ref_table)}.${esc(fk.ref_columns.join(", "))}</code> <span class="constraint-name">${esc(fk.name)}</span></li>`).join("") : "<li>Sem chaves estrangeiras nesta tabela.</li>";
  const uniqueHtml = table.unique.length ? table.unique.map(u => `<li><code>${esc(u.columns.join(", "))}</code> <span class="constraint-name">${esc(u.name)}</span></li>`).join("") : "<li>Sem constraints UNIQUE adicionais.</li>";
  const checksHtml = table.checks.length ? table.checks.map(c => `<li><code>${esc(c.name)}</code><span class="check-expression">${esc(c.expression)}</span></li>`).join("") : "<li>Sem CHECK de tabela declarado.</li>";
  const permissions = Object.entries(table.rbac).map(([role,perm]) => `<span class="role-pill"><b>${esc(role)}</b> ${esc(perm)}</span>`).join("");
  const allRows = table.columns.map(col => renderFieldRow(table,col)).join("");
  return `<section class="table-section panel-card" id="${id}" data-table="${esc(table.name)}" data-table-search="${esc((table.name+" "+table.description).toLowerCase())}">
    <div class="table-section-header"><div><div class="table-eyebrow">ENTIDADE RELACIONAL</div><h2>${esc(table.name)}</h2><p>${esc(table.description)}</p></div><div class="table-count">${table.column_count} <small>colunas</small></div></div>
    <div class="table-meta"><span><i class="fa-solid fa-key"></i> PK: ${esc(table.pk.join(", ") || "não identificada")}</span><span><i class="fa-solid fa-link"></i> ${table.fks.length} FKs</span><span><i class="fa-solid fa-shield-halved"></i> RBAC da seção 3.1</span><span><i class="fa-solid fa-user-lock"></i> Responsável de origem: ${esc(table.actors)}</span></div>
    <div class="field-table-wrap"><table class="field-table"><thead><tr><th>Atributo</th><th>Descrição / Regra de Negócio</th><th>Tipo e Tamanho</th><th>Constraints</th><th>Privacidade (LGPD)</th><th>Linhagem (Data Lineage)</th><th>Controle de Acesso (RBAC)</th></tr></thead><tbody>${allRows}</tbody></table></div>
    <details class="integrity-details"><summary><i class="fa-solid fa-list-check me-2"></i>Integridade e relacionamentos da tabela</summary><div class="integrity-grid"><div><h3>Chaves estrangeiras</h3><ul>${fkHtml}</ul></div><div><h3>Unicidade</h3><ul>${uniqueHtml}</ul></div><div><h3>Checks / domínio</h3><ul>${checksHtml}</ul></div></div></details>
  </section>`;
}

function renderDictionary() {
  const nav = document.getElementById("sidebarTableNav");
  const content = document.getElementById("dictionarySections");
  document.getElementById("sidebarTableCount").textContent = DATA_TABLES.length;
  nav.innerHTML = DATA_TABLES.map(t => `<a class="side-link table-side-link" href="#tabela_${esc(t.name)}" data-nav-table="${esc(t.name)}"><span class="nav-table-dot"></span>${esc(t.name)}<small>${t.columns.length}</small></a>`).join("");
  content.innerHTML = DATA_TABLES.map(renderTable).join("");
  document.getElementById("resultsCounter").textContent = `Exibindo ${DATA_TABLES.length} tabelas · ${DATA_TABLES.reduce((n,t)=>n+t.columns.length,0)} colunas`;
}

function applyFilters() {
  const query = document.getElementById("dictionarySearch").value.trim().toLowerCase();
  let visibleTables=0, visibleColumns=0;
  DATA_TABLES.forEach(table => {
    const section=document.getElementById(`tabela_${table.name}`);
    const rows=[...section.querySelectorAll(".field-row")];
    let tableHasVisible=false;
    rows.forEach(row => {
      const matchText = !query || row.dataset.search.includes(query) || table.name.toLowerCase().includes(query) || table.description.toLowerCase().includes(query);
      const matchPrivacy = privacyFilter === "all" || row.dataset.privacy === privacyFilter;
      const visible=matchText && matchPrivacy;
      row.hidden=!visible;
      if (visible) { tableHasVisible=true; visibleColumns++; }
    });
    const tableMatch = !query || table.name.toLowerCase().includes(query) || table.description.toLowerCase().includes(query);
    // A busca por nome da tabela mostra todas as linhas dessa tabela.
    if (tableMatch && privacyFilter === "all") {
      rows.forEach(row=>{row.hidden=false;});
      if (!tableHasVisible) visibleColumns += rows.length;
      tableHasVisible=true;
    }
    section.hidden=!tableHasVisible;
    if (tableHasVisible) visibleTables++;
    const navLink=document.querySelector(`[data-nav-table="${table.name}"]`);
    if (navLink) navLink.hidden=!tableHasVisible;
  });
  document.getElementById("resultsCounter").textContent=`Exibindo ${visibleTables} tabelas · ${visibleColumns} colunas`;
  document.getElementById("emptyState").hidden=visibleTables!==0;
}

function setPrivacyFilter(value) {
  privacyFilter=value;
  document.querySelectorAll("[data-privacy-filter]").forEach(btn=>btn.classList.toggle("active",btn.dataset.privacyFilter===value));
  applyFilters();
}

function initSearch() {
  const input=document.getElementById("dictionarySearch");
  input.addEventListener("input",applyFilters);
  document.getElementById("clearSearch").addEventListener("click",()=>{input.value="";setPrivacyFilter("all");input.focus();});
  document.querySelectorAll("[data-privacy-filter]").forEach(btn=>btn.addEventListener("click",()=>setPrivacyFilter(btn.dataset.privacyFilter)));
  document.addEventListener("keydown",e=>{if ((e.metaKey||e.ctrlKey) && e.key.toLowerCase()==="k"){e.preventDefault();input.focus();} if(e.key==="Escape" && document.activeElement===input){input.value="";applyFilters();input.blur();}});
}

function initTheme() {
  const key="ifood-dictionary-theme";
  const button=document.getElementById("themeToggle");
  const saved=localStorage.getItem(key);
  if(saved==="dark") document.body.classList.add("theme-dark");
  const icon=button.querySelector("i");
  const refresh=()=>{icon.className=document.body.classList.contains("theme-dark")?"fa-solid fa-sun":"fa-solid fa-moon";};
  refresh();
  button.addEventListener("click",()=>{document.body.classList.toggle("theme-dark");localStorage.setItem(key,document.body.classList.contains("theme-dark")?"dark":"light");refresh();});
}

function initSidebar() {
  const sidebar=document.getElementById("sidebar");
  const scrim=document.getElementById("sidebarScrim");
  const close=()=>{sidebar.classList.remove("sidebar-open");scrim.classList.remove("show");};
  document.getElementById("mobileMenuButton").addEventListener("click",()=>{sidebar.classList.toggle("sidebar-open");scrim.classList.toggle("show");});
  scrim.addEventListener("click",close);
  sidebar.addEventListener("click",e=>{if(e.target.closest("a")) close();});
  document.querySelectorAll(".side-link").forEach(link=>link.addEventListener("click",()=>{document.querySelectorAll(".side-link").forEach(x=>x.classList.remove("active"));link.classList.add("active");}));
}

function initDER() {
  const modal=document.getElementById("derModal");
  const img=document.getElementById("derImage");
  const stage=document.getElementById("derStage");
  modal.addEventListener("shown.bs.modal",()=>{
    if(typeof window.Panzoom!=="function") {
      if(!stage.querySelector(".viewer-load-error")) stage.insertAdjacentHTML("beforeend", "<p class=\"viewer-load-error\">A biblioteca de zoom não foi carregada. Confira sua conexão e recarregue a página.</p>");
      return;
    }
    const loadMessage=stage.querySelector(".viewer-load-error");
    if(loadMessage) loadMessage.remove();
    if(!panzoomInstance) {
      panzoomInstance=window.Panzoom(img,{maxScale:8,minScale:0.25,contain:"outside",step:0.25,canvas:false});
      stage.addEventListener("wheel",event=>{
        if(!panzoomInstance) return;
        event.preventDefault();
        panzoomInstance.zoomWithWheel(event);
      },{passive:false});
    } else {
      panzoomInstance.reset({animate:false});
    }
    panzoomReady=true;
  });
  modal.addEventListener("hidden.bs.modal",()=>{if(panzoomInstance)panzoomInstance.reset({animate:false});});
  document.getElementById("derZoomIn").addEventListener("click",()=>{if(panzoomInstance)panzoomInstance.zoomIn();});
  document.getElementById("derZoomOut").addEventListener("click",()=>{if(panzoomInstance)panzoomInstance.zoomOut();});
  document.getElementById("derReset").addEventListener("click",()=>{if(panzoomInstance)panzoomInstance.reset({animate:true});});
}

function initDDL() {
  const modal=document.getElementById("ddlModal");
  const code=document.getElementById("ddlCode");
  modal.addEventListener("shown.bs.modal",()=>{if(window.Prism) Prism.highlightElement(code);});
  document.getElementById("copyDDL").addEventListener("click",async()=>{
    const button=document.getElementById("copyDDL");
    const feedback=document.getElementById("copyFeedback");
    const raw=code.textContent;
    try { await navigator.clipboard.writeText(raw); button.innerHTML='<i class="fa-solid fa-check me-2"></i>Copiado!'; feedback.textContent="Script SQL copiado para a área de transferência."; }
    catch(err) { feedback.textContent="A cópia automática foi bloqueada pelo navegador. Selecione o código e copie manualmente."; }
    setTimeout(()=>{button.innerHTML='<i class="fa-regular fa-copy me-2"></i>Copiar DDL';feedback.textContent="";},2600);
  });
  document.getElementById("downloadDDL").addEventListener("click",()=>{
    const blob=new Blob([code.textContent],{type:"text/sql;charset=utf-8"});
    const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="DDL_iFood_Grupo2_v1.sql";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
  });
}

document.addEventListener("DOMContentLoaded",()=>{
  renderTeam();renderDictionary();initSearch();initTheme();initSidebar();initDER();initDDL();
});
